<?php elseif($page==='sql'):
$sqlServers=$servers;$sidFilter=max(0,(int)($_GET['server_id']??0));$playerQ=trim((string)($_GET['q']??''));
if($sidFilter>0){require_perm('sql.view',$sidFilter);$sqlServers=array_values(array_filter($servers,fn($x)=>(int)$x['id']===$sidFilter));if(!$sqlServers){http_response_code(404);exit('Server not found');}}
$scopeIds=array_values(array_map(fn($x)=>(int)$x['id'],$sqlServers));$scopePlace=$scopeIds?implode(',',array_fill(0,count($scopeIds),'?')):'NULL';
$totals=['players'=>0,'kills'=>0,'deaths'=>0,'play_seconds'=>0];$ranking=[];$recentGame=[];$snap24=[];$sqlConnections=[];
if($scopeIds){
    $st=db()->prepare('SELECT COUNT(*) players,COALESCE(SUM(kills),0) kills,COALESCE(SUM(deaths),0) deaths,COALESCE(SUM(play_seconds),0) play_seconds FROM player_stats WHERE server_id IN ('.$scopePlace.')');$st->execute($scopeIds);$totals=$st->fetch()?:$totals;
    $rankWhere='ps.server_id IN ('.$scopePlace.')';$rankArgs=$scopeIds;if($playerQ!==''){$rankWhere.=' AND (ps.name LIKE ? OR ps.steam_id LIKE ?)';$rankArgs[]='%'.$playerQ.'%';$rankArgs[]='%'.$playerQ.'%';}
    $rankSql='SELECT ps.*,s.name server_name,GREATEST(0,ps.kills*2+ps.headshots-ps.deaths+FLOOR(ps.play_seconds/600)) rating,ROUND(ps.kills/GREATEST(ps.deaths,1),2) kd FROM player_stats ps JOIN servers s ON s.id=ps.server_id WHERE '.$rankWhere.' ORDER BY rating DESC,ps.kills DESC,ps.play_seconds DESC LIMIT 100';$st=db()->prepare($rankSql);$st->execute($rankArgs);$ranking=$st->fetchAll();
    $st=db()->prepare('SELECT ge.*,s.name server_name FROM game_events ge JOIN servers s ON s.id=ge.server_id WHERE ge.server_id IN ('.$scopePlace.') ORDER BY ge.id DESC LIMIT 100');$st->execute($scopeIds);$recentGame=$st->fetchAll();
    $st=db()->prepare('SELECT ss.server_id,s.name server_name,MAX(ss.players) peak_players,ROUND(AVG(ss.players),1) avg_players,COUNT(*) snapshots,MAX(ss.recorded_at) last_recorded FROM server_stats ss JOIN servers s ON s.id=ss.server_id WHERE ss.recorded_at>=NOW()-INTERVAL 24 HOUR AND ss.server_id IN ('.$scopePlace.') GROUP BY ss.server_id,s.name ORDER BY s.id DESC');$st->execute($scopeIds);$snap24=$st->fetchAll();
    $st=db()->prepare('SELECT c.*,s.name server_name FROM server_sql_connections c JOIN servers s ON s.id=c.server_id WHERE c.server_id IN ('.$scopePlace.') ORDER BY s.id DESC');$st->execute($scopeIds);$sqlConnections=$st->fetchAll();
}
